//! Golden vectors of XXH3 and the plane-hash layout `rehoboam/rh-snapshot/hash/v1` (SPR-007 T-01).
//!
//! `tests/golden/rh_snapshot_hash_v1.txt` is generated by `bin/gen_hash_golden.py`, an
//! independent standard-library implementation of XXH3 and the layout; this test reproduces every
//! line with `twox-hash` and `rh_snapshot::hash`. A mismatch means the layout or the hash changed,
//! which is a C3 change; the golden file is never edited by hand. Hash stability across runs and
//! machines follows: the expected values are fixed text.
//!
//! REF: `crates/rh-snapshot/src/hash.rs` (the layout); Architect ruling 1 of SPR-007.
#![allow(clippy::unwrap_used, clippy::panic, reason = "tests")]

use std::collections::BTreeMap;

use rh_core::world::WorldTables;
use rh_snapshot::hash::{Plane, PlaneDigest, TableDigest, plane_hash, state_hash, xxh3, xxh3_128};

const GOLDEN: &str = include_str!("golden/rh_snapshot_hash_v1.txt");
const GAMMA: u64 = 0x9E37_79B9_7F4A_7C15;

fn input_bytes(len: usize) -> Vec<u8> {
    (0..len)
        .map(|j| u8::try_from((131 * j + len) & 0xFF).unwrap())
        .collect()
}

fn column(salt: u64, rows: usize) -> Vec<i64> {
    (0..rows as u64)
        .map(|i| ((i + 1).wrapping_mul(GAMMA) ^ salt).cast_signed())
        .collect()
}

fn bytes_rows(rows: usize) -> Vec<Vec<u8>> {
    (0..rows)
        .map(|i| vec![u8::try_from(i & 0xFF).unwrap(); i % 7])
        .collect()
}

fn hex64(s: &str) -> u64 {
    u64::from_str_radix(s, 16).unwrap()
}

fn plane_of(letter: &str) -> Plane {
    match letter {
        "A" => Plane::A,
        "B" => Plane::B,
        "C" => Plane::C,
        other => panic!("unknown plane {other}"),
    }
}

fn check_table(line: &str, digest: &TableDigest, expected: &[&str]) {
    assert_eq!(digest.root, hex64(expected[0]), "root: {line}");
    let chunks: Vec<u64> = expected[1..].iter().map(|h| hex64(h)).collect();
    assert_eq!(digest.chunks, chunks, "chunks: {line}");
}

#[test]
fn every_golden_line_reproduces() {
    let mut counts: BTreeMap<&str, usize> = BTreeMap::new();
    for line in GOLDEN.lines().filter(|l| !l.starts_with('#')) {
        let f: Vec<&str> = line.split(' ').collect();
        *counts.entry(f[0]).or_default() += 1;
        match f[0] {
            "xxh3_64" => {
                let data = input_bytes(f[1].parse().unwrap());
                assert_eq!(xxh3(&data), hex64(f[2]), "{line}");
            }
            "xxh3_128" => {
                let data = input_bytes(f[1].parse().unwrap());
                let expected = u128::from_str_radix(f[2], 16).unwrap().to_be_bytes();
                assert_eq!(xxh3_128(&data), expected, "{line}");
            }
            "column" => {
                let rows = column(f[1].parse().unwrap(), f[2].parse().unwrap());
                check_table(line, &TableDigest::of(rows.as_slice()), &f[3..]);
            }
            "bytes" => {
                let rows = bytes_rows(f[1].parse().unwrap());
                check_table(line, &TableDigest::of(rows.as_slice()), &f[2..]);
            }
            "plane" => {
                let plane = plane_of(f[1]);
                let t: usize = f[2].parse().unwrap();
                let mut tables = BTreeMap::new();
                for k in 0..t {
                    let name = f[3 + 3 * k];
                    let rows = column(f[4 + 3 * k].parse().unwrap(), f[5 + 3 * k].parse().unwrap());
                    tables.insert(name.to_owned(), TableDigest::of(rows.as_slice()));
                }
                let expected = hex64(f[3 + 3 * t]);
                let roots: Vec<(&str, u64)> =
                    tables.iter().map(|(n, d)| (n.as_str(), d.root)).collect();
                assert_eq!(plane_hash(plane, roots).unwrap(), expected, "{line}");
                assert_eq!(
                    PlaneDigest::from_tables(plane, tables.clone()).hash,
                    expected
                );
                if plane == Plane::A {
                    // The same tables as world columns: `state_hash` is this plane hash.
                    let mut world = WorldTables::new();
                    for k in 0..t {
                        let rows =
                            column(f[4 + 3 * k].parse().unwrap(), f[5 + 3 * k].parse().unwrap());
                        world.insert(f[3 + 3 * k], rows);
                    }
                    assert_eq!(state_hash(&world), expected, "{line}");
                }
            }
            other => panic!("unknown golden record {other:?}"),
        }
    }
    // Every record kind is present, so an empty or truncated file cannot pass.
    assert_eq!(counts.get("xxh3_64"), Some(&268));
    assert_eq!(counts.get("xxh3_128"), Some(&268));
    assert_eq!(counts.get("column"), Some(&7));
    assert_eq!(counts.get("bytes"), Some(&4));
    assert_eq!(counts.get("plane"), Some(&6));
}
